mapper.update:
UPDATE tb_authorityinfo SET
    USE_AT = #{useAt},
    UPD_DT = GETDATE(),
    UPD_ID = #{lastUpdusrId}
WHERE AUTHORITY_CODE = #{authorityCode}

mapper.select:
WITH MenuTree AS ( SELECT m.MENU_ID, m.PARENT_MENU_ID, m.MENU_NM, m.MENU_ORDR, CAST(RIGHT('00000' + CAST(m.MENU_ORDR AS VARCHAR), 5) AS VARCHAR(MAX)) AS SORT_PATH, 1 AS DEPTH FROM tb_menu_info m WHERE m.PARENT_MENU_ID IS NULL UNION ALL SELECT c.MENU_ID, c.PARENT_MENU_ID, c.MENU_NM, c.MENU_ORDR, mt.SORT_PATH + '-' + RIGHT('00000' + CAST(c.MENU_ORDR AS VARCHAR), 5), mt.DEPTH + 1 FROM tb_menu_info c INNER JOIN MenuTree mt ON c.PARENT_MENU_ID = mt.MENU_ID ) SELECT rmp.RMP_ID as roleMenuId, rmp.AUTHORITY_CODE as authorityCode, rmp.MENU_ID as menuId, rmp.PERMISSION_ID as permissionId, rmp.USE_AT as useAt, rmp.CRT_DT as frstRegistPnttm, rmp.CRT_ID as frstRegisterId, rmp.UPD_DT as lastUpdtPnttm, rmp.UPD_ID as lastUpdusrId, a.AUTHORITY_NM as authorityNm, mt.MENU_NM as menuNm, m.MENU_URL as menuUrl, p.PERMISSION_NM as permissionNm, p.PERMISSION_LEVEL as permissionLevel FROM tb_role_menu_permission rmp LEFT JOIN tb_authorityinfo a ON rmp.AUTHORITY_CODE = a.AUTHORITY_CODE LEFT JOIN MenuTree mt ON rmp.MENU_ID = mt.MENU_ID LEFT JOIN tb_menu_info m ON rmp.MENU_ID = m.MENU_ID LEFT JOIN tb_permission_type p ON rmp.PERMISSION_ID = p.PERMISSION_ID WHERE rmp.USE_AT = 'Y'
AND rmp.AUTHORITY_CODE = #{authorityCode}
AND rmp.MENU_ID = #{menuId}
AND rmp.PERMISSION_ID = #{permissionId}
ORDER BY mt.SORT_PATH

mapper.delete:
DELETE FROM tb_role_menu_permission
WHERE AUTHORITY_CODE = #{authorityCode}
AND MENU_ID = #{menuId}

    AND PERMISSION_ID = #{permissionId}
